<?php
/**
 * Вымышленные таблицы учета оборудования для теста импорта истории (tests/specs/eqhistory-import.spec.js) —
 * раскладка, которую разбирает импорт (App\SQS\EqHistory), данные выдуманы:
 *  - census.xlsx: таблица переписи, листы по видам (шапка в две строки, «адрес» на две колонки, «инв. №» во второй строке) и «СПИСАНО»;
 *  - issues.xlsx: таблица выдачи, лист «обычные» (№, дата регистрации, ФИО, адрес и телефон в одной ячейке, кем направлен, ...);
 *  - osv-01.xls: ведомость 1С по счету 01 с единицами, которые должны быть в базе до импорта истории.
 * Номера единиц и договоров — от числа $base, чтобы тест можно было повторять на той же базе.
 * Запуск внутри web-контейнера (нужен PhpSpreadsheet): php make-eqhistory.php <папка> <base 7 цифр> <метка>
 */
require '/var/www/html/vendor/autoload.php';

use PhpOffice\PhpSpreadsheet\Spreadsheet;

[$_, $dir, $base, $tag] = $argv;
$base = intval($base);
$inv = fn(int $k) => '0' . ($base + $k);      // инвентарный номер 1С: 8 цифр с ведущим нулем
$cn = fn(int $k, string $yy) => (intval(substr((string)$base, -5)) + $k) . '/' . $yy;
$who = fn(int $k) => "Подопечный {$tag}-" . sprintf('%03d', $k);
$d = fn(string $s) => \PhpOffice\PhpSpreadsheet\Shared\Date::PHPToExcel(new DateTime($s));

function fill($sheet, array $rows, array $dates = []) {
    foreach ($rows as $r => $row) {
        foreach ($row as $c => $v) {
            if ($v === null) {
                continue;
            }
            $sheet->setCellValueExplicit([$c + 1, $r + 1], $v, is_string($v) ? 's' : 'n');
            if (in_array($c, $dates, true) && is_float($v)) {
                $sheet->getStyle([$c + 1, $r + 1])->getNumberFormat()->setFormatCode('dd.mm.yyyy');
            }
        }
    }
}

// ---------- ведомость 1С, счет 01 ----------
$book = new Spreadsheet();
$rows = [['Учреждение (тест)'], ['Оборотно-сальдовая ведомость по счету 01.1 за 01.01.24'], ['Счет', 'Сальдо на начало периода'],
         ['Основные средства', 'Дебет', 'Кредит'], ['01.1 (по счету: 01)', 9000]];
foreach ([1, 2, 3, 5, 6, 8, 9, 10] as $k) {
    $rows[] = ["Концентратор кислорода ЭИ тестовый, инв.№: " . $inv($k), 1000];
}
$rows[] = ['Итого развернутое', 9000];
fill($book->getActiveSheet(), $rows);
(new \PhpOffice\PhpSpreadsheet\Writer\Xls($book))->save("$dir/osv-01.xls");

// ---------- перепись ----------
$book = new Spreadsheet();
$s = $book->getActiveSheet();
$s->setTitle('концентр. кисл.');
fill($s, [
    ['№ договора', 'дата', 'ФИО', 'адрес', null, 'телефон', 'наименование', 'зав. №.', null, 'дата   возврата', 'срок пользования', null],
    [null, null, null, null, null, null, 'оборудования', null, 'инв. №', null, null, null],
    // 1: выдача и возврат; та же выдача есть в журнале (там номер без ведущего нуля)
    // «подарили» (ответ 1.10) — обычная выдача, слово в примечании документа
    [$cn(1, '25'), $d('2025-01-10'), $who(1), 'г. Тестов', 'ул. Тестовая, 1', '375291110001', 'Концентратор ЭИ', 'ZV-' . $tag . '-1', $inv(1), $d('2025-03-20'), 'до востр.', 'подарили'],
    // 2: до востребования, получатель «умер» — единица остается у него
    [$cn(2, '25'), $d('2025-02-15'), $who(2), 'г. Тестов', 'ул. Тестовая, 2', '375291110002', 'Концентратор ЭИ', null, $inv(2), null, 'до востребования', 'умер'],
    // 3: списан с датой — возврат и списание
    [$cn(3, '24'), $d('2024-05-05'), $who(3), 'г. Тестов', 'ул. Тестовая, 3', '375291110003', 'Концентратор ЭИ', null, $inv(3), $d('2025-06-01'), 'списан', null],
    // ошибки: текст вместо даты; инв. номера нет в базе; две единицы в ячейке. «Вернули» без даты (ответ 1.12) — не ошибка:
    // единица 5 выдана снова 03.04.2025 (журнал), возврат — накануне
    [$cn(4, '25'), 'весна', $who(4), 'г. Тестов', 'ул. Тестовая, 4', null, 'Концентратор ЭИ', null, $inv(4), null, 'до востр.', null],
    [$cn(7, '25'), $d('2025-04-01'), $who(7), 'г. Тестов', 'ул. Тестовая, 7', null, 'Концентратор ЭИ-404', null, $inv(99), null, 'до востр.', null],
    [$cn(8, '25'), $d('2025-04-02'), $who(8), 'г. Тестов', 'ул. Тестовая, 8', null, 'Концентратор ЭИ', null, $inv(5), 'вернули', 'до востр.', null],
    [$cn(9, '25'), $d('2025-04-03'), $who(9), 'г. Тестов', 'ул. Тестовая, 9', null, 'Концентратор ЭИ', null, $inv(5) . ', ' . $inv(6), null, 'до востр.', null],
    // «вернули» без даты, больше не выдавалась — возврат датой импорта; «списан» без даты — возврат и списание датой импорта
    [$cn(14, '25'), $d('2025-05-01'), $who(14), 'г. Тестов', 'ул. Тестовая, 14', null, 'Концентратор ЭИ', null, $inv(8), 'вернули', 'до востр.', null],
    [$cn(15, '25'), $d('2025-05-02'), $who(15), 'г. Тестов', 'ул. Тестовая, 15', null, 'Концентратор ЭИ', null, $inv(9), null, 'списан', null],
], [1, 9]);
$s->mergeCells('D1:E2');

$s = $book->createSheet();
$s->setTitle('кровати');
fill($s, [
    ['№ договора', 'дата', 'ФИО', 'адрес', 'телефон', 'наименование', 'зав. №.', null, 'дата   возврата', 'срок пользования'],
    [null, null, null, null, null, 'оборудования', null, 'инв. №', null, null],
    // только заводской номер — единица создается товаром «по листу»
    [$cn(10, '25'), $d('2025-03-01'), $who(10), 'ул. Тестовая, 10', '375291110010', 'кровать функц.', 'KR1-' . $tag, null, null, 'до востр.'],   // с цифрой: номер без цифр импорт считает пометкой («нет», «мв»), а метка прогона бывает из одних букв
    // перечень единиц без выдачи (нет договора, даты и ФИО) — пропуск со сводкой
    [null, null, null, null, null, 'кровать функц.', 'KR1-' . $tag . '-2', null, null, null],
    // без номеров (ответ 5.12): кровать — не мелочь, в список «без инвентарного номера»; матрас на листе кроватей —
    // позиция по наименованию в строке, а не по листу
    [$cn(22, '25'), $d('2025-06-10'), $who(22), 'ул. Тестовая, 22', null, null, null, null, null, 'до востр.'],
    [$cn(23, '25'), $d('2025-06-11'), $who(23), 'ул. Тестовая, 23', null, 'матрас к кровати', null, null, null, 'до востр.'],
], [1, 8]);

// мелочь без номеров (ответ 1.13): на руках — количеством на позицию по наименованию в строке (с объемом, ответ 5.3),
// возвращенная — пропуск со сводкой
$s = $book->createSheet();
$s->setTitle('мешки Амбу');
fill($s, [
    ['№ договора', 'дата', 'ФИО', 'адрес', 'телефон', 'наименование', 'зав. №.', null, 'дата   возврата', 'срок пользования'],
    [null, null, null, null, null, 'оборудования', null, 'инв. №', null, null],
    [$cn(16, '25'), $d('2025-06-01'), $who(16), 'ул. Тестовая, 16', null, 'Амбу 680 мл.', null, null, null, 'до востр.'],
    [$cn(17, '25'), $d('2025-06-02'), $who(17), 'ул. Тестовая, 17', null, 'мешок Амбу', null, null, $d('2025-07-01'), 'до востр.'],
], [1, 8]);

$s = $book->createSheet();
$s->setTitle('СПИСАНО');
fill($s, [
    [null, 'концентратор'],
    // единица на складе: только списание на дату из строки
    [$cn(12, '23'), $d('2023-02-01'), $who(12), 'ул. Тестовая, 12', null, null, 'Концентратор ЭИ', null, $inv(6), $d('2025-09-01')],
    // без даты списания — датой импорта
    [$cn(18, '23'), $d('2023-03-01'), $who(18), 'ул. Тестовая, 18', null, null, 'Концентратор ЭИ', null, $inv(10), null],
], [1, 9]);
(new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($book))->save("$dir/census.xlsx");

// ---------- журнал ----------
$book = new Spreadsheet();
$s = $book->getActiveSheet();
$s->setTitle('обычные');
$no = intval(substr((string)$base, -5));
fill($s, [
    ['№', 'дата регистрации договора', 'ФИО', 'Адрес проживания, телефон', 'Кем направлен', 'Наименование оборудования', 'Инв (заводской) №', 'Дата выдачи', 'дата возврата', 'примечание'],
    // та же выдача, что строка 3 переписи: номер числом без ведущего нуля
    [(float)($no + 1), $d('2025-01-10'), $who(1), 'ул. Тестовая, 1 +375 29 111-00-01', 'Поликлиника тестовая', 'концентратор', (float)($base + 1), $d('2025-01-10'), $d('2025-03-20'), 'до востребования'],
    // только в журнале: дата выдачи пустая — берется дата договора; номер — «№/ГГ»
    [(float)($no + 5), $d('2025-04-03'), $who(5), 'ул. Тестовая, 5 +375 29 111-00-05', 'Врач тестовый', 'концентратор', $inv(5), null, null, 'до востребования'],
    // номера нет ни в базе, ни в переписи
    [(float)($no + 13), $d('2025-04-04'), $who(13), 'ул. Тестовая, 13', '-', 'ингалятор', 'XX-' . $tag, $d('2025-04-04'), null, null],
    // без номера: та же выдача, что на листе «мешки Амбу» (договор и дата) — одна; только в журнале — позиция по наименованию
    [(float)($no + 16), $d('2025-06-01'), $who(16), 'ул. Тестовая, 16', 'Врач тестовый', 'мешок Амбу', null, $d('2025-06-01'), null, 'до востребования'],
    [(float)($no + 19), $d('2025-06-05'), $who(19), 'ул. Тестовая, 19', 'Врач тестовый', 'ингалятор детский', null, $d('2025-06-05'), null, null],
    // другое написание того же вида — та же позиция по соответствиям; написания нет в соответствиях — ошибка, не импортируется
    [(float)($no + 20), $d('2025-06-06'), $who(20), 'ул. Тестовая, 20', 'Врач тестовый', 'Ингалят.детский', null, $d('2025-06-06'), null, null],
    [(float)($no + 21), $d('2025-06-07'), $who(21), 'ул. Тестовая, 21', 'Врач тестовый', 'аспиратор тестовый', null, $d('2025-06-07'), null, null],
    // без номера: кровать (позиция со «*» в соответствиях) и концентратор (товар с серийным учетом) — не мелочь
    [(float)($no + 24), $d('2025-06-12'), $who(24), 'ул. Тестовая, 24', 'Врач тестовый', 'кровать функциональная', null, $d('2025-06-12'), null, null],
    [(float)($no + 25), $d('2025-06-13'), $who(25), 'ул. Тестовая, 25', 'Врач тестовый', 'концентратор', null, $d('2025-06-13'), null, null],
], [1, 7, 8]);
$s = $book->createSheet();
$s->setTitle('дорогие');
fill($s, [['№', 'дата регистрации договора', 'ФИО', 'Адрес проживания, телефон', 'Наименование оборудования', 'Инв (заводской) №', 'Дата выдачи', 'дата возврата', 'примечание'], [1.0], [2.0]]);
(new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($book))->save("$dir/issues.xlsx");
echo "ok\n";
